            createdAt: string;
            /** Format: uuid */
            createdByAgentId?: string | null;
            createdByUserId?: string | null;
            fields?: Record<string, never>;
            /** Format: uuid */
            id: string;
            /** @description Human-readable identifier (e.g. `cm1-c24`). */
            identifier: string;
            key?: string | null;
            /** Format: uuid */
            parentCaseId?: string | null;
            /** Format: uuid */
            projectId?: string | null;
